def compute(vars):
    redemption = vars["v1"]
    accrued_interest = vars["v2"]

    if redemption == 0:
        return None

    portion = accrued_interest / redemption
    return {
        "value": portion,
        "trace": {
            "redemption": redemption,
            "accrued_interest": accrued_interest,
            "portion": portion,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
